eq(base.dtype,"int32","out/int32/U4/reverse_rows: backing source: dtype")
eq(a.shape,{3,4},"out/int32/U4/reverse_rows: source shape")
eq(a.strides,{-16,4},"out/int32/U4/reverse_rows: source strides")
eq(out:tolist(),{{"","","",""},{"","","",""}},"out/int32/U4/reverse_rows: output state")
